   Put("First_Float = ");
   Put(First_Float);
   New_Line;
   Put("Second_Float = ");
   Put(Second_Float);
   New_Line;

   -- Swap two strings
   First_String := "Ada";
   Second_String := "Programming";
   Swap(First_String, Second_String);
   Put("After swapping two strings: ");
   Put("First_String = ");
   Put(First_String);
   New_Line;
   Put("Second_String = ");
   Put(Second_String);
   New_Line;
